import urllib.request
import urllib.error
import time

class APIClientError(Exception):
    pass

class RateLimitError(APIClientError):
    pass

class ServerError(APIClientError):
    pass

class ClientError(APIClientError):
    pass

class ConnectionError(APIClientError):
    pass

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url.rstrip('/')
        self.timeout = timeout

    def get(self, path):
        url = f"{self.base_url}/{path.lstrip('/')}"

        # Retry configurations: (exception_type, max_retries, backoff_strategy)
        # backoff_strategy: list of seconds or a single float for constant
        rate_limit_backoffs = [0.5, 1, 2]

        retries_429 = 0
        retries_5xx = 0
        retries_net = 0

        while True:
            try:
                with urllib.request.urlopen(url, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')

            except urllib.error.HTTPError as e:
                code = e.code

                if code == 429:
                    if retries_429 < len(rate_limit_backoffs):
                        time.sleep(rate_limit_backoffs[retries_429])
                        retries_429 += 1
                        continue
                    raise RateLimitError(f"Rate limit exceeded after retries: {e}")

                elif 500 <= code < 600:
                    if retries_5xx < 1:
                        time.sleep(1)
                        retries_5xx += 1
                        continue
                    raise ServerError(f"Server error after retry: {e}")

                elif 400 <= code < 500:
                    raise ClientError(f"Client error: {e}")

                raise APIClientError(f"Unexpected HTTP error: {e}")

            except urllib.error.URLError as e:
                if retries_net < 1:
                    time.sleep(1)
                    retries_net += 1
                    continue
                raise ConnectionError(f"Network error after retry: {e}")
